{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeat testing is undocumented; this does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not demonstrate consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 address repeatability and alternative precision evidence, here reinterpreted as consistency across AI evaluation runs. Applicable precision evidence is insufficient, corresponding to 0 rather than 1; actual instability is not demonstrated."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeat findings, stability is unestablished; the passage does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3, 9.7 and 9.8, explicitly absent repeat testing leaves repeatability unsupported. Human retesting is reinterpreted as rerunning the same AI configuration. Missing precision evidence warrants 0 for that evidence, not a finding of poor consistency."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated scores were examined with the stated conditions held constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the reported score range as alternative precision evidence; 9.3 is reinterpreted as AI repeat testing. Findings support the defined stability claim under these conditions, without establishing broader reliability. No correlation coefficient or human sample-size rating is inferred."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly reports repeated evaluation under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed spread exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 distinguishes conducting a precision study from obtaining satisfactory results. Reinterpreting retesting as repeated AI runs, these findings demonstrate inadequate stability against the stated criterion, rather than merely missing evidence. Section 9.8 requires judgment about the intended comparison."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation supplies no evidence that repeat testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "Download and dependency instructions do not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns software instructions, whereas 9.3, 9.7 and 9.8 concern precision. Improved installation guidance does not supply repeatability findings. AI reruns replace human retesting here; applicable repeatability evidence remains insufficient, not demonstrably inadequate."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved more exact-grid successes on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish a difference in general intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 2.1, 2.2 and 3 describe the domain, purpose and scoring; 10.1 and 10.5 assess whether interpretations fit the evidence. Treating AI systems as assessed entities, the observed narrow comparison is supported. Broader construct interpretation lacks evidence; this does not prove the broad claim false."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better evaluated grid-puzzle performance by A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended cross-domain selection use does not supply evidence supporting that inference."
        }
      ],
      "instrument_review": "EFPA 6.1, 10.1, 10.3 and 10.5 require evidence supporting the stated interpretation and use. With AI systems as assessed entities, grid results support the narrow comparison but leave the intended general-intelligence selection unsupported. Validity for that use is critical; insufficient evidence is distinct from demonstrated invalidity."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied setting; the reported difference interval is wholly positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness findings do not establish an improvement in the unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 recognizes experimental evidence; 10.3.2 considers relevant outcomes, criterion quality and study adequacy. The trial supports comparative assistance effectiveness for workshop correctness. Without a reported relationship between benchmark scores and outcomes, it does not establish predictive validity of the benchmark itself. Human inspectors are outcome-study participants; AI systems remain the benchmark's assessed entities."
    }
  ],
  "closing_note": "No material task ambiguity remains. The instruction to apply the complete original EFPA model is read alongside the explicit permission to provide only probe-relevant sections. Parts A–C remain the framework; other documentation, materials, norms, precision, validity, fair-use and report questions are unassessed where evidence is absent. Human age, handedness, sensory or motor accommodations, and feedback to an AI as a human test taker are inapplicable as written; AI configuration, interface and stakeholder reporting require explicit reinterpretation. Missing information is not automatically inapplicability or poor quality. No aggregate quality score or EFPA endorsement is implied. Framework attribution: EFPA Test Review Model 2025, version 5.0, https://www.efpa.eu/, CC BY-SA 4.0; AI-specific reinterpretations are identified above."
}
